const _idb = (function(){
  let dbp = null;
  function open(){ if(dbp) return dbp; dbp = new Promise((res)=>{
    try{ const r = indexedDB.open('tingbook_db', 1);
      r.onupgradeneeded = ()=>{ try{ r.result.createObjectStore('kv'); }catch(e){} };
      r.onsuccess = ()=>res(r.result); r.onerror = ()=>res(null);
    }catch(e){ res(null); } }); return dbp; }
  return {
    async set(k,v){ const db=await open(); if(!db) return; try{ db.transaction('kv','readwrite').objectStore('kv').put(v,k); }catch(e){} },
    async get(k){ const db=await open(); if(!db) return null; return await new Promise((res)=>{ try{ const r=db.transaction('kv','readonly').objectStore('kv').get(k); r.onsuccess=()=>res(r.result??null); r.onerror=()=>res(null); }catch(e){ res(null); } }); }
  };
})();
async function saveProgress(){
  if(!currentPlay.file) return;
  const pl = (currentPlay.playlist && currentPlay.playlist.length) ? currentPlay.playlist.map(x=>BOOKS.indexOf(x)) : null;
  const data = JSON.stringify({ file:currentPlay.file, name:currentPlay.name, text:currentPlay.text,
    time:audio.currentTime||0, duration:audio.duration||0, playlist:pl, index:currentPlay.index, ts:Date.now() });
  try{ localStorage.setItem(PROGRESS_KEY, data); }catch(e){}
  await _idb.set(PROGRESS_KEY, data);
}
async function loadProgress(){
  try{ const v = localStorage.getItem(PROGRESS_KEY); if(v) return JSON.parse(v); }catch(e){}
  const v = await _idb.get(PROGRESS_KEY);
  if(v){ try{ return JSON.parse(v); }catch(e){ return null; } }
  return null;
}
async function clearProgress(){
  try{ localStorage.removeItem(PROGRESS_KEY); }catch(e){}
  await _idb.set(PROGRESS_KEY, null);
}
// ---- 按篇记忆播放位置（用于上一篇/下一篇续播）----
const POS_KEY = 'tingbook_positions_v1';
function loadPositions(){ try{ return JSON.parse(localStorage.getItem(POS_KEY)||'{}'); }catch(e){ return {}; } }
function savePositions(p){ try{ localStorage.setItem(POS_KEY, JSON.stringify(p)); }catch(e){} }
function setPos(file, t){ if(!file) return; const p=loadPositions(); p[file]=Math.max(0, Math.floor(t||0)); savePositions(p); }
function getPos(file){ if(!file) return 0; const p=loadPositions(); const v=p[file]; return (typeof v==='number' && v>0) ? v : 0; }
function clearPos(file){ if(!file) return; const p=loadPositions(); delete p[file]; savePositions(p); }
function applySpeed(){
  const v = parseFloat(document.getElementById('pp-speed').value) || 1;
  audio.playbackRate = v;
  try{ localStorage.setItem(SPEED_KEY, String(v)); }catch(e){}
}
function setSleep(min){
  clearTimeout(sleepTimer); clearInterval(sleepInterval);
  const lbl = document.getElementById('timer-label');
  if(!min){ lbl.textContent=''; return; }
  sleepEnd = Date.now() + min*60000;
  sleepTimer = setTimeout(()=>{ audio.pause(); lbl.textContent='已关闭'; document.getElementById('pp-timer').value='0';
    setTimeout(()=>lbl.textContent='',1500); }, min*60000);
  sleepInterval = setInterval(()=>{
    const left = Math.max(0, sleepEnd - Date.now());
    const m = Math.floor(left/60000), s = Math.floor((left%60000)/1000);
    lbl.textContent = '剩 '+m+':'+String(s).padStart(2,'0');
  }, 1000);
}

function setupContinueAll(prog){
  const btn=document.getElementById('continue-all');
  if(prog && prog.playlist && prog.playlist.length && prog.time>=3){
    const idx = (typeof prog.index==='number' && prog.index>=0) ? prog.index : 0;
    const bk = BOOKS[prog.playlist[idx]];
    const name = (bk && bk.title) || prog.name || '列表';
    btn.textContent = `⏯ 继续播放（第 ${idx+1}/${prog.playlist.length} 首：${name}）`;
    btn.style.display='';
    continueProg = prog;
  } else {
    btn.style.display='none';
    continueProg = null;
  }
}
function showResume(prog){
  // 整列表续播（记忆了 playlist）统一交给顶部「⏯ 继续播放」按钮，避免重复提示
  if(prog && prog.playlist && prog.playlist.length){
    document.getElementById('resume-card').style.display='none';
    setupContinueAll(prog);
    return;
  }
  const card=document.getElementById('resume-card');
  const valid = prog && prog.file && prog.time>=3;
  if(!valid){ card.style.display='none'; resumeBar.style.display='none';
    document.getElementById('pp-resume').style.display='none'; setupContinueAll(null); return; }
  const name = prog.name || '上次收听';
  const when = prog.ts ? new Date(prog.ts).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}) : '';
  card.style.display='';
  document.getElementById('resume-title').textContent='继续播放：'+name;
  document.getElementById('resume-meta').textContent='进度 '+fmtTime(prog.time)+(prog.duration? ' / '+fmtTime(prog.duration):'')+(when? '（上次 '+when+'）':'');
  document.getElementById('resume-go').onclick=()=>resumePlay(prog);
  document.getElementById('rb-title').innerHTML='继续播放：'+name+'<small>进度 '+fmtTime(prog.time)+(prog.duration?' / '+fmtTime(prog.duration):'')+(when?' · 上次 '+when:'')+'</small>';
  resumeBar.dataset.prog = JSON.stringify(prog);
  document.getElementById('pp-resume').style.display='';
  document.getElementById('pp-resume').onclick=()=>resumePlay(prog);
  updateResumeBar();
  setupContinueAll(null);
}
function updateResumeBar(){
  const has = resumeBar.dataset.prog;
  if(playerPage.classList.contains('show')){ resumeBar.style.display='none'; return; }
  resumeBar.style.display = has ? 'flex' : 'none';
}
function resumePlay(prog){
  resumeBar.style.display='none';
  if(prog.playlist && prog.playlist.length){
    playlist = prog.playlist.map(i=>BOOKS[i]).filter(Boolean);
    playingAll=true; plIndex=prog.index>=0?prog.index:0;
    document.getElementById('play-all').style.display='none';
    document.getElementById('stop-all').style.display='';
    currentPlay={file:playlist[plIndex].file,name:playlist[plIndex].title,text:playlist[plIndex].text,playlist,index:plIndex};
    playBook(playlist[plIndex], prog.time);
  }else{
    currentPlay={file:prog.file,name:prog.name,text:prog.text,playlist:null,index:-1};
    playBook({file:prog.file,name:prog.name,text:prog.text}, prog.time);
  }
}

function splitSentences(text){
  if(!text) return [];
  const seps = '。！？；…\n';
  let out=[], cur='';
  for(const ch of text){ cur+=ch; if(seps.includes(ch)){ out.push(cur.trim()); cur=''; } }
  if(cur.trim()) out.push(cur.trim());
  return out.filter(s=>s.length);
}
function buildTimeline(sentences, duration){
  const total = sentences.reduce((a,s)=>a+s.length,0) || 1;
  let acc=0; const marks=[];
  for(const s of sentences){ const start=(acc/total)*duration; acc+=s.length; marks.push([start,(acc/total)*duration]); }
  return marks;
}
function renderSubtitle(text){
  curSentences = splitSentences(text); curMarks=null; curActive=-1;
  if(!curSentences.length){ subtitleEl.style.display='none'; subtitleEl.innerHTML=''; return; }
  subtitleEl.style.display='block'; subtitleEl.innerHTML='';
  curSentences.forEach((s,i)=>{
    const span=document.createElement('span'); span.className='sent'; span.textContent=s; span.dataset.i=i;
    span.onclick=()=>{
      if(tingMode==='clone'){
        regenSentence(s, null);
        span.classList.add('active');
        setTimeout(()=>span.classList.remove('active'), 600);
      } else if(curMarks&&curMarks[i]){
        audio.currentTime=curMarks[i][0]; audio.play().catch(()=>{});
      }
    };
    const regen=document.createElement('button');
    regen.type='button'; regen.className='sent-regen'; regen.textContent='↻';
    regen.title='用克隆音重新生成这一句的朗读（听我读）';
    regen.addEventListener('click', (e)=>{ e.stopPropagation(); regenSentence(s, regen); });
    span.appendChild(regen);
    subtitleEl.appendChild(span);
  });
  highlight(-1);
}
function highlight(i){
  if(i===curActive) return;
  const els=subtitleEl.children;
  if(curActive>=0 && els[curActive]) els[curActive].classList.remove('active');
  curActive=i;
  if(i>=0 && els[i]){ els[i].classList.add('active'); els[i].scrollIntoView({block:'center',behavior:'smooth'}); }
}
function showPlayerPage(){ playerPage.classList.add('show'); }
function hidePlayerPage(){ playerPage.classList.remove('show'); }
function hideResumeBars(){ resumeBar.style.display='none'; const rc=document.getElementById('resume-card'); if(rc) rc.style.display='none'; }
function updateNowPlaying(){ const np=document.getElementById('now-playing'); if(currentPlay.name){ np.style.display=''; np.textContent='🎵 '+currentPlay.name; } }
function playBook(b, startTime){
  const _isMusic = !!window.__musicPending; window.__musicPending = false; window.__tingCtx = _isMusic ? 'music' : 'read';
  advanceGuard = false;   // 新一首开场即解除“播完”兜底锁，避免续播被误判为已处理
  const _f = b.file || b.audio || b.url;
  if(startTime === undefined) startTime = getPos(_f);   // 未显式指定起点 -> 续播该篇上次位置
  startTime = startTime || 0;
  const cb=document.getElementById('continue-all'); if(cb) cb.style.display='none';
  continueProg=null;
  const src = b.file || b.audio || b.url;     // 流式版用 .file；单文件用 .audio/.url
  const nm = b.title || b.name;
  playingAll = playingAll && playlist.length > 0;
  currentPlay = { file:src, name:nm, text:b.text, playlist: playingAll?playlist:null, index: playingAll?plIndex:-1 };
  hideResumeBars();
  playerNow.textContent=nm;
  const dl=document.getElementById('pp-dl'); dl.href = src||'#'; if(nm) dl.setAttribute('download', nm+'.mp3');
  audio.src=src; renderSubtitle(b.text); applySpeed();
  const seekPlay=()=>{ try{ if(startTime>0) audio.currentTime=startTime; }catch(e){} audio.play().catch(()=>{}); };
  // preload=none 时仅设置 src 不会发起网络请求，必须主动 play() 触发流式加载（否则死锁）
  audio.play().catch(()=>{});
  if(audio.readyState>=1) seekPlay(); else audio.addEventListener('loadedmetadata', seekPlay, {once:true});
  showPlayerPage(); playerPage.classList.toggle('music', window.__tingCtx === 'music'); updateNowPlaying();
  updateMediaSession();
  saveProgress();
}
audio.addEventListener('loadedmetadata', ()=>{ curMarks=null; if('mediaSession' in navigator && audio.duration){ try{ navigator.mediaSession.setPositionState({duration:audio.duration, position:audio.currentTime, playbackRate:audio.playbackRate||1}); }catch(e){} } });
audio.addEventListener('timeupdate', ()=>{
  if(audio.duration){
    ppSeek.value = Math.min(1000, Math.floor(audio.currentTime/audio.duration*1000));
    ppTime.textContent = fmtTime(audio.currentTime)+' / '+fmtTime(audio.duration);
  }
  if(!curSentences.length) return;
  if(!curMarks && audio.duration) curMarks=buildTimeline(curSentences, audio.duration);
  if(curMarks){
    const t=audio.currentTime; let idx=-1;
    for(let i=0;i<curMarks.length;i++){ if(t>=curMarks[i][0]&&t<curMarks[i][1]){ idx=i; break; } }
    if(idx===-1 && t>=audio.duration) idx=curMarks.length-1;
    highlight(idx);
  }
  if('mediaSession' in navigator && audio.duration && isFinite(audio.duration)){ try{ navigator.mediaSession.setPositionState({duration:audio.duration, position:Math.min(audio.currentTime,audio.duration), playbackRate:audio.playbackRate||1}); }catch(e){} }
  const now=Date.now();
  if(now-lastSave>3000 && (currentPlay.file||currentPlay.url)){ lastSave=now; saveProgress(); setPos(currentPlay.file||currentPlay.url, audio.currentTime); }
});
audio.addEventListener('pause', ()=>{ document.getElementById('pp-play').textContent='▶'; if('mediaSession' in navigator){ try{ navigator.mediaSession.playbackState='paused'; }catch(e){} } saveProgress(); updateResumeBar(); setPos(currentPlay.file||currentPlay.url, audio.currentTime); });
audio.addEventListener('play', ()=>{ advanceGuard=false; document.getElementById('pp-play').textContent='⏸'; if('mediaSession' in navigator){ try{ navigator.mediaSession.playbackState='playing'; }catch(e){} } });
// 统一处理“一首播完”：单曲循环 / 列表循环 / 顺序播放下一首 / 全部播完
// advanceGuard 防止 ended 与下方 timeupdate 兜底对同一首重复触发（否则会一次跳两首）
function onTrackEnded(){
  if(advanceGuard) return; advanceGuard = true;
  document.getElementById('pp-play').textContent='▶';
  if(loopMode==='one'){ audio.currentTime=0; audio.play().catch(()=>{}); advanceGuard=false; return; }
  if(loopMode==='all'){
    const list = (playingAll && playlist.length) ? playlist : BOOKS;
    let idx = (playingAll && playlist.length) ? plIndex : BOOKS.findIndex(b => (b.file||b.audio||b.url) === currentPlay.file);
    if(idx < 0) idx = 0;
    const n = (idx + 1) % list.length;            // 列表循环：播完自动跳下一篇，末尾回第 1 篇
    playlist = (playingAll && playlist.length) ? playlist : BOOKS.slice();
    playingAll = true;
    document.getElementById('play-all').style.display='none';
    document.getElementById('stop-all').style.display='';
    plIndex = n;
    playItem(n, 'start');
    return;
  }
  if(playingAll && plIndex<playlist.length-1){ playItem(plIndex+1, 'start'); return; }
  clearProgress(); clearPos(currentPlay.file||currentPlay.url);
  resumeBar.dataset.prog=''; showResume(null);
  // 网页不关闭就一直播放：整本列表播完后循环回第 1 篇继续，不自动停止（用户可手动暂停/停止）
  playlist = (playingAll && playlist.length) ? playlist : BOOKS.slice();
  playingAll = true;
  document.getElementById('play-all').style.display='none';
  document.getElementById('stop-all').style.display='';
  document.getElementById('playing-all-status').textContent='♾️ 循环播放中（列表播完自动回到开头）';
  plIndex = 0;
  playItem(0, 'start');
  return;
}
audio.addEventListener('ended', onTrackEnded);
// ===== 锁屏/后台连续播放支持：Media Session API =====
// 不接入时，锁屏或切后台浏览器会挂起 JS，ended/timeupdate 不派发，下一首的 play() 起不来；
// 接入后媒体会话在后台保持活跃，ended 能正常触发，系统锁屏也能显示曲目并提供上一首/下一首按钮。
function msNext(){
  if(playingAll && playlist.length){ const n=(plIndex+1)%playlist.length; playItem(n,'start'); return; }
  const idx=BOOKS.findIndex(b=>(b.file||b.audio||b.url)===currentPlay.file);
  if(idx>=0){ playlist=BOOKS.slice(); playingAll=true; plIndex=(idx+1)%BOOKS.length; playItem(plIndex,'start'); }
  else if(audio.src){ audio.currentTime=0; audio.play().catch(()=>{}); }
}
function msPrev(){
  if(playingAll && playlist.length){ const n=(plIndex-1+playlist.length)%playlist.length; playItem(n,'start'); return; }
  const idx=BOOKS.findIndex(b=>(b.file||b.audio||b.url)===currentPlay.file);
  if(idx>0){ playlist=BOOKS.slice(); playingAll=true; plIndex=idx-1; playItem(plIndex,'start'); }
  else if(audio.src){ audio.currentTime=0; audio.play().catch(()=>{}); }
}
function updateMediaSession(){
  if(!('mediaSession' in navigator)) return;
  try{
    navigator.mediaSession.metadata = new MediaMetadata({
      title: currentPlay.name || '听我读',
      artist: 'tingbook',
      album: '听我读 · 倾听你的声音',
      artwork: [{ src: 'assets/bg-girl.webp', sizes: '512x512', type: 'image/webp' }]
    });
    navigator.mediaSession.playbackState = 'playing';
  }catch(e){}
}
if('mediaSession' in navigator){
  try{
    navigator.mediaSession.setActionHandler('play', ()=>audio.play().catch(()=>{}));
    navigator.mediaSession.setActionHandler('pause', ()=>audio.pause());
    navigator.mediaSession.setActionHandler('nexttrack', msNext);
    navigator.mediaSession.setActionHandler('previoustrack', msPrev);
    navigator.mediaSession.setActionHandler('seekto', (d)=>{ if(d && d.seekTime!=null){ try{ audio.currentTime=d.seekTime; }catch(e){} } });
  }catch(e){}
}
// 兜底：部分流式音频 / 个别浏览器 ended 事件不触发，用 timeupdate 检测接近结尾来续播
audio.addEventListener('timeupdate', ()=>{
  if(!advanceGuard && audio.duration && audio.currentTime >= audio.duration - 0.4) onTrackEnded();
});

// ===== 锁屏/切后台自动恢复播放 =====
// 手机锁屏或切后台时，浏览器会暂停 <audio>（iOS 必现，部分 Android 也会），
// 解锁/切回前台后不会自动恢复。媒体会话(mediaSession)只解决"后台续播下一首"，
// 不负责"恢复当前这一首"。这里跟踪播放意图(wantPlaying)：只有在可见状态下
// 用户主动暂停才清掉意图；锁屏导致的暂停(此时 visibilityState==='hidden')保留意图。
// 回到前台(可见)且意图仍为播放、音频却处于暂停时，自动 resume。
let wantPlaying = false;
audio.addEventListener('play', ()=>{ wantPlaying = true; });
audio.addEventListener('pause', ()=>{
  // 可见状态下暂停 = 用户主动暂停，不再自动恢复
  if(document.visibilityState === 'visible') wantPlaying = false;
});
function tryResume(){
  if(document.visibilityState === 'hidden') return;
  if(audio.paused && wantPlaying){
    audio.play().catch(()=>{});
    if('mediaSession' in navigator){ try{ navigator.mediaSession.playbackState='playing'; }catch(e){} }
  }
}
document.addEventListener('visibilitychange', tryResume);
window.addEventListener('pageshow', tryResume);   // 从 bfcache 恢复（iOS 常见）

function playItem(i, mode){
  if(i<0||i>=playlist.length) return;
  plIndex=i; const b=playlist[i];
  document.querySelectorAll('#list .card').forEach((c,j)=>{
    c.classList.toggle('playing', BOOKS[j] && BOOKS[j].title===b.title);
  });
  document.getElementById('playing-all-status').textContent=`正在播放 ${i+1}/${playlist.length}：${b.title}`;
  // mode='start' -> 从头播；'resume'(默认) -> 续播上次位置
  playBook(b, mode==='start' ? 0 : undefined);
}
function playAll(){
  playlist=BOOKS.slice(); playingAll=true; plIndex=0;
  document.getElementById('play-all').style.display='none';
  document.getElementById('stop-all').style.display='';
  playItem(0, 'start');
}
function stopAll(){
  playingAll=false; playlist=[]; plIndex=-1; audio.pause();
  document.getElementById('play-all').style.display='';
  document.getElementById('stop-all').style.display='none';
  document.getElementById('playing-all-status').textContent='';
  document.getElementById('now-playing').style.display='none';
  hidePlayerPage(); hideNp();
  document.querySelectorAll('#list .card.playing').forEach(c=>c.classList.remove('playing'));
}
document.getElementById('play-all').onclick=playAll;
document.getElementById('continue-all').onclick=()=>{ if(continueProg) resumePlay(continueProg); };
document.getElementById('stop-all').onclick=stopAll;

// ---------------- 播放页控制 ----------------
function togglePlay(){ if(audio.paused) audio.play().catch(()=>{}); else audio.pause(); }
function renderPlaylist(){
  const el=document.getElementById('pp-playlist'); el.innerHTML='';
  BOOKS.forEach((b,i)=>{
    if(isHidden(b.file)) return;
    const d=document.createElement('div');
    d.className='pl-item'+(currentPlay.name===b.title?' active':'');
    d.textContent=(i+1)+'. '+b.title;
    d.onclick=()=>{ playlist=BOOKS.slice(); playingAll=true; plIndex=i;
      document.getElementById('play-all').style.display='none';
      document.getElementById('stop-all').style.display='';
      document.getElementById('playing-all-status').textContent=`正在播放 ${i+1}/${BOOKS.length}：${b.title}`;
      playBook(b, 0); document.getElementById('pp-playlist').classList.remove('show'); };
    el.appendChild(d);
  });
}
document.getElementById('pp-play').onclick=togglePlay;
function currentBookIndex(){
  if(playingAll && playlist.length) return plIndex;
  return BOOKS.findIndex(b => b.file === currentPlay.file);
}
function stepTrack(dir, mode){
  let list, i;
  if(playingAll && playlist.length){ list = playlist; i = plIndex; }
  else { list = BOOKS; i = BOOKS.findIndex(b => b.file === currentPlay.file); playlist = BOOKS.slice(); }
  if(i < 0) return;
  const j = i + dir;
  if(j < 0 || j >= list.length) return;     // 手动切歌边界不环绕
  plIndex = j;
  playItem(j, mode || 'resume');   // 上一篇/下一篇默认续播上次位置
}
document.getElementById('pp-prev').onclick=()=>stepTrack(-1, 'resume');
document.getElementById('pp-next').onclick=()=>stepTrack(1, 'resume');
function restartCurrent(){
  const b = (playingAll && playlist.length) ? playlist[plIndex] : BOOKS[currentBookIndex()];
  const f = (b && (b.file||b.audio||b.url)) || currentPlay.file || currentPlay.url;
  if(f) clearPos(f);                 // 清空本篇续播进度
  try{ audio.currentTime = 0; }catch(e){}
  audio.play().catch(()=>{});
}
document.getElementById('pp-restart').onclick=restartCurrent;
document.getElementById('pp-back').onclick=()=>hidePlayerPage();
document.getElementById('pp-list-toggle').onclick=()=>{ renderPlaylist(); document.getElementById('pp-playlist').classList.toggle('show'); };
document.getElementById('pp-seek').addEventListener('input', ()=>{ if(audio.duration) audio.currentTime=(ppSeek.value/1000)*audio.duration; });
document.getElementById('now-playing').onclick=()=>showPlayerPage();

document.getElementById('pp-speed').onchange = applySpeed;
document.getElementById('pp-timer').onchange = e => setSleep(parseInt(e.target.value,10)||0);
// ---------------- 循环播放（重复播放） ----------------
const loopBtn = document.getElementById('pp-loop');
function updateLoopBtn(){
  const map = { off:'🔁 循环：关', one:'🔂 单曲循环', all:'🔁 列表循环' };
  loopBtn.textContent = map[loopMode];
  const on = loopMode !== 'off';
  loopBtn.style.background = on ? 'var(--accent2)' : '';
  loopBtn.style.color = on ? '#06281c' : '';
}
loopBtn.onclick = () => {
  loopMode = loopMode === 'off' ? 'one' : loopMode === 'one' ? 'all' : 'off';
  updateLoopBtn();
};
updateLoopBtn();
document.getElementById('rb-go').onclick = ()=>{ const p=resumeBar.dataset.prog; if(p) resumePlay(JSON.parse(p)); };
document.getElementById('rb-close').onclick = ()=>{ resumeBar.style.display='none'; };
window.addEventListener('beforeunload', saveProgress);

// ---------------- 我的听单：删除功能（同步删除 GitHub 仓库文件） ----------------
// 说明：点击删除会调用后台 /api/delete（Cloudflare Pages Function），真正从 GitHub 仓库
// 删除音频文件并从 index.html 的 BOOKS 中移除条目；成功后本地视图才隐藏。
const HIDDEN_KEY = 'ltyv_hidden_files_v1';
function loadHidden(){ try{ return new Set(JSON.parse(localStorage.getItem(HIDDEN_KEY)||'[]')); }catch(e){ return new Set(); } }
function saveHidden(s){ try{ localStorage.setItem(HIDDEN_KEY, JSON.stringify([...s])); }catch(e){} }
let hiddenFiles = loadHidden();
const ADMIN_KEY = "ltyv-del-2026"; // 需与 Cloudflare Pages 环境变量 ADMIN_KEY 设为相同值，后端删除才会生效（否则仅本地隐藏）
async function deleteBackend(file){
  try{
    const r = await fetch('/api/delete', {method:'POST', headers:{'content-type':'application/json','x-admin-key':ADMIN_KEY}, body: JSON.stringify({file})});
    if(!r.ok) return false;
    const j = await r.json().catch(()=>({}));
    return !!j.ok;
  }catch(e){ return false; }
}
function isHidden(f){ return hiddenFiles.has(f); }
function hideFile(f){ hiddenFiles.add(f); saveHidden(hiddenFiles); updateRestoreRow(); }
function updateRestoreRow(){ const r=document.getElementById('restore-row'); if(r) r.style.display = hiddenFiles.size ? 'block' : 'none'; }
function restoreAll(){ hiddenFiles.clear(); saveHidden(hiddenFiles); location.reload(); }
const restoreBtn = document.getElementById('restore-hidden');
if(restoreBtn) restoreBtn.onclick = restoreAll;
updateRestoreRow();

const COVER_GRADIENTS=[
  'linear-gradient(135deg,#caa45a,#8a5a2f)',
  'linear-gradient(135deg,#5b8def,#2a4a8a)',
  'linear-gradient(135deg,#ec7a7a,#a83a3a)',
  'linear-gradient(135deg,#5bbf8f,#2a7a5a)',
  'linear-gradient(135deg,#9b7adf,#5a3aa8)',
  'linear-gradient(135deg,#e0a85a,#a86a2a)',
  'linear-gradient(135deg,#56c2c9,#2a7a82)',
  'linear-gradient(135deg,#d98ac0,#8a3a72)'
];
if(listEl){ BOOKS.forEach((b,i)=>{
  if(isHidden(b.file)) return;
  const card=document.createElement('div'); card.className='card'; card.dataset.title=b.title;
  const dl = document.createElement('a');
  dl.className='badge'; dl.textContent='⬇'; dl.href=b.file; dl.setAttribute('download', b.title+'.mp3'); dl.title='下载 MP3';
  const cover=document.createElement('div'); cover.className='book-cover'; cover.style.background=COVER_GRADIENTS[i%COVER_GRADIENTS.length];
  cover.innerHTML='<div class="bc-title">'+b.title+'</div>';
  cover.appendChild(dl);
  const title=document.createElement('div'); title.className='book-title'; title.textContent=b.title;
  const meta=document.createElement('div'); meta.className='book-meta'; meta.textContent='时长 '+b.duration+'s';
  const actions=document.createElement('div'); actions.className='book-actions';
  const play=document.createElement('button'); play.className='play-btn'; play.textContent='▶ 朗读';
  const del=document.createElement('button'); del.className='del-btn'; del.textContent='🗑'; del.title='从听单移除';
  actions.appendChild(play); actions.appendChild(del);
  card.appendChild(cover); card.appendChild(title); card.appendChild(meta); card.appendChild(actions);
  play.onclick=()=>{ stopAll(); card.classList.add('playing'); playBook(b, 0); };
  del.onclick=async ()=>{
    if(!confirm('永久删除《'+b.title+'》？\n这将从服务器删除音频并移除播放条目，且无法撤销。')) return;
    const ok = await deleteBackend(b.file);   // 先同步删除 GitHub 仓库文件
    if(ok){ hideFile(b.file); card.remove(); } // 成功后再隐藏本地视图
    else alert('后台删除失败：未删除服务器文件。可稍后重试，或到仓库手动删除。');
  };
  listEl.appendChild(card);
  });
}

