// ---------------- 听我读（浏览器内置 TTS，纯前端） ----------------
const tingInput = document.getElementById('ting-input');
const tingVoice = document.getElementById('ting-voice');
const tingStatus = document.getElementById('ting-status');

function loadTingVoices(){
  try{
    const vs = speechSynthesis.getVoices();
    tingVoice.innerHTML = '';
    const zh = vs.filter(v => /zh|cmn|Chinese|Yue|Han/i.test(v.lang));
    const list = zh.length ? zh : vs;
    list.forEach((v)=>{
      const o = document.createElement('option');
      o.value = v.voiceURI; o.textContent = v.name + ' (' + v.lang + ')';
      tingVoice.appendChild(o);
    });
    if(!zh.length) tingStatus.textContent = '提示：当前浏览器无中文语音，将用默认嗓音';
  }catch(e){}
}
if ('speechSynthesis' in window){
  loadTingVoices();
  speechSynthesis.onvoiceschanged = loadTingVoices;
} else {
  tingStatus.textContent = '当前浏览器不支持语音合成';
}

// AI 自动识别：匹配 BOOKS 篇名；命中则朗读该篇全文，否则朗读原文
function normalize(s){ return (s||'').replace(/[\s""''《》<>【】()（）.,，。、！？!?：:；;]/g,'').toLowerCase(); }
function resolveTingText(raw){
  const q = normalize(raw);
  if(!q) return { text: raw, label: '自由文本' };
  let best = null, bestScore = 0;
  for(const b of BOOKS){
    const t = normalize(b.title);
    let score = 0;
    if(q.includes(t) || t.includes(q)) score = Math.max(q.length, t.length);
    else { const set = new Set(t); let hit = 0; for(const c of q) if(set.has(c)) hit++; score = hit; }
    if(score > bestScore){ bestScore = score; best = b; }
  }
  if(best && bestScore >= 2) return { text: best.text, label: '识别为：《' + best.title + '》' };
  return { text: raw, label: '自由文本' };
}

function tingSpeak(){
  if(!('speechSynthesis' in window)){ tingStatus.textContent='浏览器不支持语音合成'; return; }
  const raw = (tingInput.value || '').trim();
  if(!raw){ tingStatus.textContent='请先输入文字或篇名'; return; }
  const { text, label } = resolveTingText(raw);
  speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  const vs = speechSynthesis.getVoices();
  const pick = vs.find(v=>v.voiceURI===tingVoice.value) || vs.find(v=>/zh|cmn|Chinese|Yue|Han/i.test(v.lang)) || vs[0];
  if(pick){ u.voice = pick; u.lang = pick.lang; }
  u.rate = 1; u.pitch = 1;
  u.onend = ()=>{ tingStatus.textContent = label + ' · 朗读结束'; };
  u.onerror = ()=>{ tingStatus.textContent = label + ' · 朗读出错'; };
  speechSynthesis.speak(u);
  tingStatus.textContent = label + ' · 朗读中…';
}
function tingStop(){ try{ speechSynthesis.cancel(); }catch(e){} try{ if(window.__tingAudio){ window.__tingAudio.pause(); window.__tingAudio = null; } }catch(e){} tingStatus.textContent='已停止'; }

// ---------------- 克隆音模式：调用 /api/ting-read（后端 F5-TTS） ----------------
async function tingCloneSpeak(){
  const raw = (tingInput.value || '').trim();
  if(!raw){ tingStatus.textContent='请先输入文字或篇名'; return; }
  const { text, label } = resolveTingText(raw);
  tingStatus.textContent = label + ' · 正在用克隆音色合成…';
  try{
    const r = await fetchTingRead(text);
    if(!r.ok) throw new Error(r.error || '克隆音服务无响应');
    const blob = r.blob;
    const url = URL.createObjectURL(blob);
    const audio = new Audio(url);
    window.__tingAudio = audio;
    audio.onended = ()=>{ tingStatus.textContent = label + ' · 朗读结束'; URL.revokeObjectURL(url); window.__tingAudio = null; };
    audio.onerror = ()=>{ tingStatus.textContent = label + ' · 播放出错'; URL.revokeObjectURL(url); window.__tingAudio = null; };
    await audio.play();
    tingStatus.textContent = label + ' · 克隆音朗读中…';
  }catch(e){
    tingStatus.textContent = '克隆音暂不可用（' + e.message + '），已退回系统嗓音';
    if('speechSynthesis' in window){
      speechSynthesis.cancel();
      const u = new SpeechSynthesisUtterance(text);
      const vs = speechSynthesis.getVoices();
      const pick = vs.find(v=>v.voiceURI===tingVoice.value) || vs.find(v=>/zh|cmn|Chinese|Yue|Han/i.test(v.lang)) || vs[0];
      if(pick){ u.voice = pick; u.lang = pick.lang; }
      speechSynthesis.speak(u);
    }
  }
}

// ---------------- 点击字幕某句：用克隆音重新生成这一句 ----------------
async function regenSentence(text, btn){
  if(!text || !text.trim()) return;
  if(btn){ btn.disabled = true; btn.classList.add('busy'); btn.classList.remove('done'); btn.textContent='⏳'; }
  try{
    const r = await fetchTingRead(text);
    if(!r.ok) throw new Error(r.error || '克隆音服务无响应');
    const blob = r.blob;
    const url = URL.createObjectURL(blob);
    const a = new Audio(url);
    a.onended = ()=>{ URL.revokeObjectURL(url); if(btn){ btn.classList.remove('busy'); btn.classList.add('done'); btn.textContent='✓'; setTimeout(()=>{ if(btn){ btn.classList.remove('done'); btn.textContent='↻'; } }, 1500); } };
    a.onerror = ()=>{ URL.revokeObjectURL(url); };
    await a.play().catch(()=>{});
  }catch(e){
    // 克隆音不可用时退回系统嗓音朗读该句
    if('speechSynthesis' in window){
      speechSynthesis.cancel();
      const u = new SpeechSynthesisUtterance(text);
      try{
        const tv = (typeof tingVoice !== 'undefined') ? tingVoice.value : null;
        const vs = speechSynthesis.getVoices();
        const pick = (tv && vs.find(v=>v.voiceURI===tv)) || vs.find(v=>/zh|cmn|Chinese|Yue|Han/i.test(v.lang)) || vs[0];
        if(pick){ u.voice = pick; u.lang = pick.lang; }
      }catch(_){}
      speechSynthesis.speak(u);
    }
    if(btn) btn.title = '克隆音暂不可用（'+e.message+'），已退回系统嗓音';
  }finally{
    if(btn){ btn.disabled = false; btn.classList.remove('busy'); if(btn.textContent==='⏳') btn.textContent='↻'; }
  }
}

