// ---------------- 多音字校准 ----------------
let polyRules=[];
const polyPanel=document.getElementById('poly-panel');
const polyRulesEl=document.getElementById('poly-rules');
document.getElementById('poly-btn').onclick=()=>{
  polyPanel.style.display = (polyPanel.style.display==='none') ? '' : 'none';
  if(polyPanel.style.display!=='none') loadPoly();
};
document.getElementById('poly-close').onclick=()=>polyPanel.style.display='none';
async function loadPoly(){
  try{ const j=await (await fetch('/api/polyphone-rules')).json(); polyRules=j.rules||[]; }
  catch(e){ polyRules=[]; }
  renderPoly();
}
function renderPoly(){
  polyRulesEl.innerHTML='';
  if(!polyRules.length){ polyRulesEl.innerHTML='<p class="meta">暂无规则。用上方输入框添加“原字 → 同音替换字”，例如：银行 → 银航（行读 háng）。</p>'; return; }
  polyRules.forEach((r,i)=>{
    const row=document.createElement('div'); row.className='poly-row';
    row.innerHTML='<label><input type="checkbox" '+(r.enabled?'checked':'')+' data-i="'+i+'" class="pe"/> <span class="pf">'+r.from+'</span> → <span class="pt">'+r.to+'</span></label><span class="meta">'+(r.note||'')+'</span>';
    const del=document.createElement('button'); del.className='badge'; del.textContent='删除';
    del.onclick=()=>{ polyRules.splice(i,1); renderPoly(); };
    row.appendChild(del);
    polyRulesEl.appendChild(row);
  });
  polyRulesEl.querySelectorAll('.pe').forEach(cb=>cb.onchange=e=>{ polyRules[+cb.dataset.i].enabled=cb.checked; });
}
document.getElementById('poly-add').onclick=()=>{
  const f=document.getElementById('poly-from').value.trim();
  const t=document.getElementById('poly-to').value.trim();
  if(!f||!t) return;
  polyRules.push({from:f,to:t,enabled:true,note:''});
  document.getElementById('poly-from').value=''; document.getElementById('poly-to').value='';
  renderPoly();
};
document.getElementById('poly-save').onclick=async ()=>{
  const msg=document.getElementById('poly-msg'); msg.textContent='保存中…';
  polyRulesEl.querySelectorAll('.pe').forEach(cb=>{ polyRules[+cb.dataset.i].enabled=cb.checked; });
  try{
    const r=await fetch('/api/polyphone-rules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rules:polyRules})});
    const j=await r.json();
    msg.textContent = (j.status==='ok') ? ('✅ 已保存 '+j.count+' 条，新生成即生效') : '❌ 保存失败';
  }catch(e){ msg.textContent='❌ 保存失败'; }
};

// ================= 内容重新分类 + 音乐（亮色）+ 全局播放条 =================
const CATS = [
  { key:'诗词', items:['将进酒','声声慢','念奴娇赤壁怀古','春江花月夜','水调歌头','沁园春长沙','沁园春雪','白头吟','蜀道难','侠客行','葬花吟','红楼梦引子','错误_郑愁予','木兰诗','长恨歌','琵琶行'] },
  { key:'辞赋', items:['洛神赋','阿房宫赋','赤壁赋','滕王阁序','离骚','逍遥游','涉江'] },
  { key:'古文', items:['出师表','岳阳楼记','师说','桃花源记','过秦论'] }
];
const CAT_SET = {};
CATS.forEach(function(c){ c.items.forEach(function(t){ CAT_SET[t] = c.key; }); });
function catOf(title){ return CAT_SET[title] || '诗词'; }

// 给已渲染的阅读卡片补上分类标记（BOOKS 渲染循环早于本段，故此处补打）
document.querySelectorAll('#list .card').forEach(function(c){
  const b = BOOKS.find(function(x){ return x.title === c.dataset.title; });
  c.dataset.cat = b ? catOf(b.title) : '';
});

// 分类 chips：点击按 dataset.cat 过滤容器内的卡片
function buildChips(chipsEl, container){
  if(!chipsEl || !container) return;
  chipsEl.innerHTML = '';
  const cats = [{key:'', label:'全部'}].concat(CATS.map(function(c){ return {key:c.key, label:c.key}; }));
  cats.forEach(function(cat, i){
    const chip = document.createElement('div');
    chip.className = 'chip' + (i===0 ? ' active' : '');
    chip.textContent = cat.label; chip.dataset.cat = cat.key;
    chip.onclick = function(){
      chipsEl.querySelectorAll('.chip').forEach(function(x){ x.classList.remove('active'); });
      chip.classList.add('active');
      Array.prototype.forEach.call(container.children, function(card){
        const show = !cat.key || card.dataset.cat === cat.key;
        card.style.display = show ? '' : 'none';
      });
    };
    chipsEl.appendChild(chip);
  });
}

// 音乐 tab：把每本书渲染成专辑（网易云风），点击即用克隆音朗读
function renderMusic(){
  const grid = document.getElementById('album-grid'); if(!grid) return;
  grid.innerHTML = '';
  BOOKS.forEach(function(b, i){
    if(isHidden(b.file)) return;
    const album = document.createElement('div'); album.className = 'album';
    album.dataset.cat = catOf(b.title); album.dataset.title = b.title;
    const cover = document.createElement('div'); cover.className = 'a-cover';
    cover.style.background = COVER_GRADIENTS[i % COVER_GRADIENTS.length];
    cover.innerHTML = '<div class="bc-title">' + b.title + '</div>';
    const play = document.createElement('button'); play.className = 'a-play'; play.textContent = '▶'; play.title = '朗读';
    cover.appendChild(play);
    const title = document.createElement('div'); title.className = 'a-title'; title.textContent = b.title;
    const sub = document.createElement('div'); sub.className = 'a-sub'; sub.textContent = catOf(b.title) + ' · 听书';
    album.appendChild(cover); album.appendChild(title); album.appendChild(sub);
    album.onclick = function(){ playFromMusic(b); };
    grid.appendChild(album);
  });
  const mc = document.getElementById('music-count'); if(mc) mc.textContent = BOOKS.length + ' 篇';
  const hc = document.getElementById('m-hero-cover'); if(hc) hc.style.background = 'linear-gradient(135deg,#ec4141,#7a1f1f)';
}

