// ---- 背景图：黑胶盘 + 电台 hero 共用同一张用户上传的图 ----
(function(){
  var BG_KEY='tingbook_bg_v1';
  function applyBg(dataUrl){
    try{ localStorage.setItem(BG_KEY, dataUrl); }catch(e){}
    var els=document.querySelectorAll('.vinyl, .m-hero .m-cover');
    for(var i=0;i<els.length;i++){
      var el=els[i];
      el.style.backgroundImage="url("+dataUrl+")";
      el.style.backgroundSize='cover';
      el.style.backgroundPosition='center center';
      el.style.backgroundRepeat='no-repeat';
      el.style.opacity='1';
    }
    // 电台 hero 方框：背景图后清掉内部图标/红渐变叠加
    var mc=document.querySelector('.m-hero .m-cover');
    if(mc) mc.innerHTML='';
  }
  var saved=null;
  try{ saved=localStorage.getItem(BG_KEY); }catch(e){}
  if(!saved){ saved='assets/bg-girl.webp'; }
  applyBg(saved);
  var inp=document.createElement('input');
  inp.type='file'; inp.accept='image/*'; inp.style.display='none';
  document.body.appendChild(inp);
  inp.addEventListener('change', function(e){
    var f=e.target.files && e.target.files[0]; if(!f) return;
    var fr=new FileReader();
    fr.onload=function(ev){
      var img=new Image();
      img.onload=function(){
        var max=900, w=img.width, h=img.height;
        if(w>max||h>max){ if(w>=h){ h=Math.round(h*max/w); w=max; } else { w=Math.round(w*max/h); h=max; } }
        var c=document.createElement('canvas'); c.width=w; c.height=h;
        c.getContext('2d').drawImage(img,0,0,w,h);
        applyBg(c.toDataURL('image/jpeg', 0.85));
      };
      img.src=ev.target.result;
    };
    fr.readAsDataURL(f);
    inp.value='';
  });
  function bindClick(id){
    var el=document.getElementById(id); if(!el) return;
    el.style.cursor='pointer';
    el.title='点击上传/更换背景图（黑胶 + 电台共用）';
    el.addEventListener('click', function(){ inp.click(); });
  }
  bindClick('pp-vinyl');
  bindClick('m-hero-cover');
})();